import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

min_reduce_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void min_reduce_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const long outer_size,
    const long reduce_size,
    const long inner_size)
{
    long total = outer_size * inner_size;
    long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long stride = gridDim.x * blockDim.x;

    for (; idx < total; idx += stride) {
        long outer_idx = idx / inner_size;
        long inner_idx = idx % inner_size;

        long base = outer_idx * reduce_size * inner_size + inner_idx;

        float min_val = input[base];
        for (long r = 1; r < reduce_size; ++r) {
            float val = input[base + r * inner_size];
            if (val < min_val) {
                min_val = val;
            }
        }
        output[idx] = min_val;
    }
}

torch::Tensor min_reduce_cuda(torch::Tensor input, int64_t dim) {
    input = input.contiguous();

    auto sizes = input.sizes();
    int ndim = sizes.size();

    long outer_size = 1;
    for (int i = 0; i < dim; ++i) {
        outer_size *= sizes[i];
    }
    long reduce_size = sizes[dim];
    long inner_size = 1;
    for (int i = dim + 1; i < ndim; ++i) {
        inner_size *= sizes[i];
    }

    std::vector<int64_t> out_sizes;
    for (int i = 0; i < ndim; ++i) {
        if (i != dim) {
            out_sizes.push_back(sizes[i]);
        }
    }

    auto output = torch::empty(out_sizes, input.options());

    long total = outer_size * inner_size;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;
    if (blocks > 65535) blocks = 65535;
    if (blocks < 1) blocks = 1;

    min_reduce_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        outer_size,
        reduce_size,
        inner_size
    );

    return output;
}
"""

min_reduce_cpp_source = r"""
torch::Tensor min_reduce_cuda(torch::Tensor input, int64_t dim);
"""

min_reduce_module = load_inline(
    name="min_reduce_module",
    cpp_sources=min_reduce_cpp_source,
    cuda_sources=min_reduce_source,
    functions=["min_reduce_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs min reduction over a specific dimension
    using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.min_reduce = min_reduce_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda()
        return self.min_reduce.min_reduce_cuda(x, self.dim)


batch_size = 128
dim1 = 4096
dim2 = 4095

def get_inputs():
    x = torch.rand(batch_size, dim1, dim2)
    return [x]

def get_init_inputs():
    return [1]

